<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {ElMessage,ElMessageBox} from 'element-plus';
import {api,get,message} from '../api';
import {useAuth} from '../stores/auth';
import Icon from '../components/Icon.vue';
import Art from '../components/DataProductArt.vue';
import {dataFieldLabels,fieldDescription} from '../data-fields';
const auth=useAuth(),route=useRoute(),router=useRouter();
const isPlatform=computed(()=>auth.user?.businessEntity.type==='PLATFORM');
const platform=computed(()=>isPlatform.value&&auth.can('data:write'));
const applicant=computed(()=>['TRADER','CARRIER'].includes(auth.user?.businessEntity.type||'')&&auth.can('data:subscribe'));
const tabs=computed(()=>[['catalog','数据产品'],['scenarios','场景应用'],['authorizations',isPlatform.value?'授权记录':'我的授权'],...(applicant.value?[['subscriptions','我的订阅']]:[]),...(platform.value?[['operations','授权审核'],['products','产品管理']]:[])]);
const tab=ref(String(route.query.tab||'catalog')),busy=ref(false),saving=ref(false),error=ref('');
const products=ref<any[]>([]),requests=ref<any[]>([]),grants=ref<any[]>([]),subscriptions=ref<any[]>([]),scenarios=ref<any[]>([]),options=ref<any>({editions:[],waybills:[],datasets:{}});
const q=ref(''),appliedQ=ref(''),theme=ref(''),state=ref(''),page=ref(1),recordTab=ref(isPlatform.value?'grants':'requests');
const detail=ref<any>(),detailTab=ref('intro'),scenario=ref<any>();
const label:Record<string,string>={PUBLISHED:'已发布',DRAFT:'草稿',REVIEW:'待发布审核',OFFLINE:'已下架',PENDING:'待审核',APPROVED:'已通过',REJECTED:'已退回',WITHDRAWN:'已撤回',ACTIVE:'使用中',SCHEDULED:'待生效',EXPIRED:'已到期',EXPIRING:'即将到期',PAUSED:'已暂停',REVOKED:'已取消',UNAVAILABLE:'产品暂不可用',PUBLIC:'公共 / 脱敏范围',AGGREGATE:'通道汇总',OWN:'本企业业务',BASIC:'基础版',STANDARD:'标准版',ENTERPRISE:'企业版',API:'API服务',FILE:'数据文件'};
const themes=['运力资源','通道态势','链路追溯','承运信用','运输风险'];
const catalog=computed(()=>products.value.filter(p=>p.profile&&p.status==='PUBLISHED').sort((a,b)=>themes.indexOf(a.theme)-themes.indexOf(b.theme)));
const statusOf=(s:any)=>s.effectiveStatus==='ACTIVE'&&new Date(s.authorization.expiresAt).getTime()-Date.now()<7*86400000?'EXPIRING':s.effectiveStatus;
const rows=computed(()=>tab.value==='catalog'?catalog.value:tab.value==='scenarios'?scenarios.value:tab.value==='subscriptions'?subscriptions.value:tab.value==='operations'?requests.value:tab.value==='products'?products.value:recordTab.value==='grants'?grants.value:requests.value);
const filtered=computed(()=>rows.value.filter(x=>{
 const product=x.product||x.authorization?.product||x;
 const text=[x.name,x.code,x.entityName,x.purpose,x.applicationName,product.name,product.theme,x.description].filter(Boolean).join(' ').toLowerCase();
 return (!appliedQ.value||text.includes(appliedQ.value.toLowerCase()))&&(!theme.value||product.theme===theme.value||x.category===theme.value)&&(!state.value||(tab.value==='subscriptions'?statusOf(x):x.effectiveStatus||x.status)===state.value);
}));
const shown=computed(()=>filtered.value.slice((page.value-1)*12,page.value*12));
const myPending=computed(()=>requests.value.filter(x=>x.status==='PENDING').length);
const type=(s:string):'success'|'warning'|'danger'|'info'=>['PUBLISHED','APPROVED','ACTIVE'].includes(s)?'success':['PENDING','SCHEDULED','EXPIRING','REVIEW'].includes(s)?'warning':['EXPIRED','REJECTED','UNAVAILABLE'].includes(s)?'danger':'info';
const date=(s:any)=>s?new Date(s).toLocaleDateString('zh-CN'):'—';
const dateTime=(s:any)=>s?new Date(s).toLocaleString('zh-CN'):'—';
const valueText=(v:any,key=''):string=>v===null||v===undefined?'—':typeof v==='number'&&/Tons$/.test(key)?v.toFixed(1):Array.isArray(v)?v.map(x=>valueText(x,key)).join('、'):typeof v==='object'?Object.entries(v).map(([k,x])=>`${dataFieldLabels[k]||({min:'下限',max:'上限',unit:'单位',type:'形式',from:'起',to:'止',effectiveOrCompletedOrders:'有效 / 已完成订单数'} as any)[k]||k}：${valueText(x,k)}`).join('；'):String(v);
const remain=(s:any)=>Math.max(0,Math.ceil((new Date(s.authorization.expiresAt).getTime()-Date.now())/86400000));
const grantFor=(p:any)=>grants.value.find(g=>g.productId===p.id&&g.entityId===auth.user?.businessEntityId&&g.effectiveStatus==='ACTIVE'&&g.productVersion===p.version);
const pendingFor=(p:any)=>requests.value.some(x=>x.productId===p.id&&x.entityId===auth.user?.businessEntityId&&x.status==='PENDING');
const grantRange=(g:any)=>g.constraints?.origin?`${g.constraints.origin} → ${g.constraints.destination}`:g.constraints?.waybillIds?.length?`指定 ${g.constraints.waybillIds.length} 个运单`:label[g.scope];
function switchTab(next:string){next=tabs.value.some(t=>t[0]===next)?next:'catalog';tab.value=next;if(isPlatform.value)recordTab.value='grants';detail.value=undefined;scenario.value=undefined;reset();router.replace({path:'/data',query:{tab:next}});}
function search(){appliedQ.value=q.value.trim();page.value=1;}
function reset(){q.value='';appliedQ.value='';theme.value='';state.value='';page.value=1;}
async function load(){busy.value=true;error.value='';try{
 const result=await Promise.all([get('/data/products'),get('/data/requests'),get('/data/authorizations'),applicant.value?get('/data/subscriptions'):Promise.resolve([]),get('/data/scenarios'),get('/data/options')]);
 [products.value,requests.value,grants.value,subscriptions.value,scenarios.value,options.value]=result;
 if(detail.value)detail.value=products.value.find(p=>p.id===detail.value.id);if(activeSub.value)activeSub.value=subscriptions.value.find(s=>s.id===activeSub.value.id)||activeSub.value;
}catch(e){error.value=message(e);}finally{busy.value=false;}}
function openProduct(p:any){detail.value=p;detailTab.value='intro';scenario.value=undefined;router.replace({path:'/data',query:{tab:tab.value,product:p.id}});window.scrollTo({top:0,behavior:'smooth'});}
function closeDetail(){detail.value=undefined;scenario.value=undefined;router.replace({path:'/data',query:{tab:tab.value}});}
watch([theme,state,recordTab],()=>page.value=1);
watch(()=>route.query.tab,v=>{const next=String(v||'catalog');if(!tabs.value.some(t=>t[0]===next))switchTab('catalog');else if(tab.value!==next){tab.value=next;reset();detail.value=undefined;scenario.value=undefined;}});
onMounted(async()=>{if(!tabs.value.some(t=>t[0]===tab.value))switchTab('catalog');await load();if(route.query.product)detail.value=products.value.find(x=>x.id===route.query.product);});

const applyOpen=ref(false),applyProduct=ref<any>(),applyStep=ref(0),formError=ref(''),period=ref<string[]>([]);
const application=ref<any>({});
function requireApplicant(){if(applicant.value)return true;ElMessage.info('仅粮食贸易企业和物流运营商可申请数据授权与订阅。');return false;}
function beginApply(p:any,edition='BASIC'){
 if(!requireApplicant())return;
 if(!p.profile||p.status!=='PUBLISHED'){ElMessage.info('该产品暂未开放申请，请选择已发布的业务数据产品。');return;}
 applyProduct.value=p;applyStep.value=0;formError.value='';const now=new Date(),to=new Date(Date.now()+90*86400000),local=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
 period.value=[local(now),local(to)];application.value={department:auth.user?.department||'',applicationName:'北粮南运业务系统',scenarios:[],purpose:'',edition,scope:p.profile.scopes[0],origin:'',destination:'',waybillIds:[],accepted:false};applyOpen.value=true;
}
function confirmApply(){if(!requireApplicant())return;const f=application.value;formError.value='';if(f.department.trim().length<2||f.applicationName.trim().length<2||!f.scenarios.length||f.purpose.trim().length<10||period.value?.length!==2){formError.value='请填写部门、应用名称、使用场景和至少10字的用途，并选择授权期限。';return;}if(applyProduct.value.dataset==='CAPACITY'&&(!f.origin.trim()||!f.destination.trim())){formError.value='请填写需要授权的起运城市与目的城市。';return;}if(applyProduct.value.dataset==='TRACE'&&!f.waybillIds.length){formError.value='请选择至少一个本企业运单。';return;}if(!f.accepted){formError.value='请阅读并勾选数据使用约定。';return;}applyStep.value=1;}
async function submitApply(){if(!requireApplicant())return;saving.value=true;formError.value='';try{
 const f={...application.value,productId:applyProduct.value.id,startsAt:new Date(period.value[0]+'T00:00:00+08:00').toISOString(),expiresAt:new Date(period.value[1]+'T23:59:59+08:00').toISOString()};
 await api.post('/data/requests',f);applyStep.value=2;await load();
}catch(e){formError.value=message(e);}finally{saving.value=false;}}
async function withdraw(x:any){if(!requireApplicant())return;try{await api.post('/data/requests/'+x.id+'/withdraw',{version:x.version,status:'WITHDRAWN'});ElMessage.success('申请已撤回');await load();}catch(e){ElMessage.error(message(e));}}
const record=ref<any>(),recordOpen=ref(false);
function showRecord(x:any){record.value=x;recordOpen.value=true;}
const reviewOpen=ref(false),reviewRow=ref<any>(),review=ref<any>({});
function beginReview(x:any){reviewRow.value=x;review.value={status:'APPROVED',note:'',dailyLimit:options.value.editions.find((e:any)=>e.id===x.edition)?.dailyLimit||100};formError.value='';reviewOpen.value=true;}
async function saveReview(){if(review.value.note.trim().length<2){formError.value='请填写审核意见。';return;}saving.value=true;formError.value='';try{await api.post('/data/requests/'+reviewRow.value.id+'/review',{...review.value,version:reviewRow.value.version});reviewOpen.value=false;ElMessage.success(review.value.status==='APPROVED'?'已通过，企业可开通订阅':'已退回，企业可查看意见后重新申请');await load();}catch(e){formError.value=message(e);}finally{saving.value=false;}}

const subscribeOpen=ref(false),subscribeGrant=ref<any>(),subscribe=ref<any>({}),issuedKey=ref(''),keyOpen=ref(false);
function beginSubscribe(g:any){if(!requireApplicant())return;subscribeGrant.value=g;subscribe.value={authorizationId:g.id,name:g.product.profile?.shortName||g.product.name,mode:g.product.serviceMode==='FILE'?'FILE':'API',frequency:'按需',dailyLimit:Math.min(g.dailyLimit,100)};formError.value='';subscribeOpen.value=true;}
async function saveSubscribe(){if(!requireApplicant())return;saving.value=true;formError.value='';try{const s=(await api.post('/data/subscriptions',subscribe.value)).data.data;issuedKey.value=s.key;keyOpen.value=true;subscribeOpen.value=false;ElMessage.success('订阅已开通');await load();}catch(e){formError.value=message(e);}finally{saving.value=false;}}
async function copyKey(){try{await navigator.clipboard.writeText(issuedKey.value);ElMessage.success('调用凭证已复制');}catch{ElMessage.info('请选中凭证手动复制');}}
async function change(model:string,x:any,next:string){try{
 if(model==='subscriptions'&&!requireApplicant())return;
 if(next==='REVOKED'||next==='OFFLINE')await ElMessageBox.confirm(next==='REVOKED'?'取消后凭证将立即失效，之后需重新开通。':'下架后所有关联订阅暂不可用。','确认操作',{confirmButtonText:'确认',cancelButtonText:'返回'});
 await api.post(`/data/${model}/${x.id}/status`,{version:x.version,status:next});ElMessage.success('状态已更新');await load();
}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e));}}
async function rotate(x:any){if(!requireApplicant())return;try{await ElMessageBox.confirm('旧凭证将立即失效，请在业务应用中替换为新凭证。','轮换调用凭证',{confirmButtonText:'轮换',cancelButtonText:'返回'});issuedKey.value=(await api.post('/data/subscriptions/'+x.id+'/key',{version:x.version,status:x.status})).data.data.key;keyOpen.value=true;await load();}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e));}}
const activeSub=ref<any>(),serviceOpen=ref(false),serviceTab=ref('query'),query=ref<any>({}),result=ref<any>(),queryError=ref('');
function manage(s:any){if(!requireApplicant())return;activeSub.value=s;serviceTab.value='query';query.value={};result.value=undefined;queryError.value='';serviceOpen.value=true;}
async function invoke(){if(!requireApplicant())return;saving.value=true;queryError.value='';try{result.value=(await api.post('/data/subscriptions/'+activeSub.value.id+'/preview',query.value)).data.data;await load();}catch(e){queryError.value=message(e);}finally{saving.value=false;}}
async function download(report=false){if(!requireApplicant())return;saving.value=true;queryError.value='';try{const r=await api.get('/data/subscriptions/'+activeSub.value.id+(report?'/report':'/file'),{params:query.value,responseType:'blob'}),json=!report&&activeSub.value.authorization.product.format==='JSON',url=URL.createObjectURL(r.data),a=document.createElement('a');a.href=url;a.download=activeSub.value.authorization.product.code+(report?'-report.md':json?'.json':'.csv');a.click();URL.revokeObjectURL(url);await load();}catch(e){queryError.value=message(e);}finally{saving.value=false;}}
const fieldRows=computed(()=>detail.value?.fields.map((key:string)=>({key,name:dataFieldLabels[key]||key,description:fieldDescription(key)}))||[]);
const productOpen=ref(false),productForm=ref<any>({}),editId=ref('');
function editProduct(p?:any){editId.value=p?.id||'';formError.value='';productForm.value=p?Object.fromEntries(['code','name','description','theme','dataset','fields','source','frequency','coverage','serviceMode','format','owner','conditions','version'].map(k=>[k,p[k]])):{code:'',name:'',description:'',theme:'运力资源',dataset:'CAPACITY',fields:[...(options.value.datasets.CAPACITY||[])],source:'平台业务台账',frequency:'按需',coverage:'北粮南运',serviceMode:'BOTH',format:'JSON',owner:'平台运营方',conditions:''};productOpen.value=true;}
async function saveProduct(){saving.value=true;formError.value='';try{if(editId.value)await api.put('/data/products/'+editId.value,productForm.value);else await api.post('/data/products',productForm.value);productOpen.value=false;ElMessage.success('已保存草稿，发布审核后可提供服务');await load();}catch(e){formError.value=message(e);}finally{saving.value=false;}}
const productNext:Record<string,string[]>={DRAFT:['REVIEW'],REVIEW:['PUBLISHED','DRAFT'],PUBLISHED:['PAUSED','OFFLINE'],PAUSED:['PUBLISHED','OFFLINE'],OFFLINE:['DRAFT']};
watch([platform,applicant],()=>{if(!tabs.value.some(t=>t[0]===tab.value))switchTab('catalog');if(isPlatform.value)recordTab.value='grants';if(!applicant.value){applyOpen.value=false;subscribeOpen.value=false;serviceOpen.value=false;keyOpen.value=false;issuedKey.value='';subscriptions.value=[];}});
</script>

<template>
 <div class="data-workspace" :class="{'data-catalog':tab==='catalog'&&!detail&&!scenario}" v-loading="busy">
  <nav class="data-tabs" aria-label="数据服务功能">
   <button v-for="t in tabs" :key="t[0]" :class="{active:tab===t[0]}" @click="switchTab(t[0])">{{t[1]}}<span v-if="t[0]==='operations'&&myPending" class="count-pill">{{myPending}}</span></button>
   <span class="data-operator"><Icon name="shield" :size="14"/>平台运营方提供授权</span>
  </nav>
  <el-alert v-if="error" :title="error" type="error" :closable="false"><el-button link @click="load">重试加载</el-button></el-alert>

  <template v-if="detail">
   <button class="back-link" @click="closeDetail"><Icon name="arrow" :size="15" class="back-icon"/>返回数据产品</button>
   <section class="product-detail-head surface">
    <Art :kind="detail.dataset"/>
    <div><div class="eyebrow">{{detail.theme}}<span>版本 {{detail.version}} · {{date(detail.updatedAt)}}</span></div><h1>{{detail.name}}</h1><p>{{detail.description}}</p><div class="detail-tags"><el-tag size="small" effect="plain">{{detail.profile?.scopeText}}</el-tag><el-tag size="small" type="info" effect="plain">{{detail.serviceMode==='BOTH'?'API / 数据文件':label[detail.serviceMode]}}</el-tag><el-tag size="small" type="info" effect="plain">{{detail.frequency}}更新</el-tag></div>
     <template v-if="applicant"><el-button v-if="grantFor(detail)" type="primary" @click="beginSubscribe(grantFor(detail))">开通订阅</el-button><el-button v-else type="primary" :disabled="pendingFor(detail)||!detail.profile" @click="beginApply(detail)">{{pendingFor(detail)?'申请审核中':'申请授权'}}</el-button></template>
    </div>
   </section>
   <div class="detail-meta surface"><div><small>覆盖范围</small><strong>{{detail.coverage}}</strong></div><div><small>产品运营</small><strong>{{detail.owner}}</strong></div><div><small>输出内容</small><strong>{{detail.fields.length}} 项授权字段 · {{detail.format}}</strong></div><div><small>交付方式</small><strong>{{detail.profile?.deliveries?.join(' / ')||label[detail.serviceMode]}}</strong></div></div>
   <section class="surface detail-body"><el-tabs v-model="detailTab">
    <el-tab-pane label="产品介绍" name="intro"><div class="intro-columns"><div><h2>数据内容</h2><ul class="content-list"><li v-for="item in detail.profile?.contents" :key="item"><Icon name="check" :size="18"/>{{item}}</li></ul><h2>适用企业</h2><div class="detail-tags"><el-tag v-for="item in detail.profile?.audience" :key="item" type="info" effect="plain">{{item}}</el-tag></div><h2>业务价值</h2><p>{{detail.description}}</p></div><aside class="source-box"><h3>当前数据来源</h3><p v-for="item in detail.profile?.sources" :key="item"><Icon name="database" :size="15"/>{{item}}</p><h3>后续可接入数据</h3><p v-for="item in detail.profile?.external" :key="item">{{item}}</p><small>当前服务以平台已登记且允许授权的业务数据为准。</small></aside></div></el-tab-pane>
    <el-tab-pane label="数据字段" name="fields"><el-table :data="fieldRows"><el-table-column prop="name" label="字段名称" width="210"/><el-table-column prop="key" label="接口字段" width="210"/><el-table-column prop="description" label="口径与权限说明" min-width="330"/></el-table></el-tab-pane>
    <el-tab-pane label="数据格式" name="format"><div class="sample-notice"><Icon name="info" :size="16"/>接口按授权范围返回已登记业务数据，输出字段及口径如下。</div><pre class="code-block">{{JSON.stringify({format:detail.format,fields:fieldRows},null,2)}}</pre><h3>接口调用</h3><pre class="code-block">GET /api/data-feed{{detail.dataset==='TRACE'?'?waybillNo=获授权运单号':detail.dataset==='CORRIDOR'?'?period=WEEK':detail.dataset==='CREDIT'?'?months=3':''}}
X-Data-Key: 您的订阅调用凭证</pre></el-tab-pane>
    <el-tab-pane label="应用场景" name="scenarios"><div class="related-scenes"><button v-for="s in scenarios.filter(s=>s.datasets.includes(detail.dataset))" :key="s.id" @click="detail=undefined;scenario=s"><Icon :name="s.icon" :size="24"/><span><strong>{{s.name}}</strong><small>{{s.description}}</small></span><Icon name="right"/></button></div></el-tab-pane>
    <el-tab-pane label="服务约定与常见问题" name="terms"><h2>使用边界</h2><p class="terms-copy">{{detail.conditions}}</p><el-collapse><el-collapse-item title="如何申请与开通订阅？" name="1">填写企业用途、使用应用与期限，由平台运营方审核；审核通过后在我的授权中开通 API 或文件订阅。</el-collapse-item><el-collapse-item title="能否转授权或查看其他企业明细？" name="2">仅允许获授权企业按用途使用。企业明细、链路核验与运单风险限授权业务范围；公共产品只提供脱敏或汇总内容。</el-collapse-item><el-collapse-item title="为什么部分结果为空？" name="3">没有来源、字段未登记或统计样本不足时返回空值。未接入的外部数据不会作为实时结果提供。</el-collapse-item><el-collapse-item title="订阅暂停或授权到期后会怎样？" name="4">数据调用立即停止；授权及调用记录保留。可按实际业务用途重新申请续期，或在有效授权内恢复暂停的订阅。</el-collapse-item></el-collapse></el-tab-pane>
   </el-tabs></section>
   <section v-if="detail.profile" class="edition-section"><h2>{{applicant?'选择服务版本':'服务版本与额度'}}</h2><p>企业按使用用途申请服务额度，范围、期限和额度由平台审核确定。</p><div class="edition-grid"><article v-for="e in options.editions" :key="e.id" class="surface"><h3>{{e.name}}</h3><strong>{{e.dailyLimit.toLocaleString()}}<small> 次 / 日</small></strong><p>授权字段白名单<br/>{{detail.profile.scopeText}}<br/>调用记录与期限管理</p><el-button v-if="applicant" :disabled="pendingFor(detail)" @click="beginApply(detail,e.id)">{{pendingFor(detail)?'申请审核中':'申请此版本'}}</el-button></article></div></section>
  </template>

  <template v-else-if="scenario">
   <button class="back-link" @click="closeDetail"><Icon name="arrow" :size="15" class="back-icon"/>返回场景应用</button>
   <section class="scenario-detail surface"><Art :kind="scenario.datasets[0]"/><div><span class="eyebrow">{{scenario.category}}</span><h1>{{scenario.name}}</h1><p>{{scenario.description}}</p><el-button type="primary" @click="router.push(scenario.path)">{{scenario.action}}<Icon name="arrow" :size="16"/></el-button></div></section>
   <section class="surface scene-process"><h2>业务流程</h2><ol><li v-for="(s,i) in scenario.steps" :key="s"><span>{{String(i+1).padStart(2,'0')}}</span>{{s}}</li></ol></section>
   <section class="surface scene-products"><h2>所需数据产品 <small>{{scenario.products.length}} 项</small></h2><p>按业务用途申请相关产品，平台审核后可独立开通所需服务。</p><el-table :data="scenario.products"><el-table-column label="产品名称" min-width="320"><template #default="{row}"><strong>{{row.profile.shortName}}</strong><small class="block-muted">{{row.description}}</small></template></el-table-column><el-table-column prop="theme" label="分类" width="110"/><el-table-column label="数据范围" min-width="180"><template #default="{row}">{{row.profile.scopeText}}</template></el-table-column><el-table-column v-if="applicant" label="我的授权" width="120"><template #default="{row}"><el-tag :type="grantFor(row)?'success':pendingFor(row)?'warning':'info'">{{grantFor(row)?'已获授权':pendingFor(row)?'审核中':'未申请'}}</el-tag></template></el-table-column><el-table-column label="操作" width="185"><template #default="{row}"><el-button link type="primary" @click="openProduct(row)">查看产品</el-button><el-button v-if="applicant&&!grantFor(row)" link type="primary" :disabled="pendingFor(row)" @click="beginApply(row)">申请</el-button><el-button v-else-if="applicant" link type="primary" @click="beginSubscribe(grantFor(row))">订阅</el-button></template></el-table-column></el-table></section>
  </template>

  <template v-else>
   <section v-if="tab==='catalog'" class="catalog-intro">
    <img class="catalog-hero-image" src="/assets/data-service/warehouse-photo-v3.webp" alt="" width="754" height="530" fetchpriority="high"/>
    <div class="catalog-hero-copy"><span class="eyebrow">北粮南运 · 数据服务</span><h1>粮食物流数据服务</h1><p>查询运力、通道、履约与风险，支持北粮南运全过程业务。</p><div class="intro-chips"><span><Icon name="database" :size="15"/>{{catalog.length}} 类业务产品</span><span><Icon name="shield" :size="15"/>按企业用途授权</span><span><Icon name="route" :size="15"/>公路 · 铁路 · 水路</span></div></div>
    <span class="hero-scene-caption" aria-hidden="true">连接产区、通道与销区</span>
   </section>
   <div v-if="tab==='authorizations'&&!isPlatform" class="record-tabs"><el-radio-group v-model="recordTab"><el-radio-button value="requests">我的申请</el-radio-button><el-radio-button value="grants">已获授权</el-radio-button></el-radio-group></div>
   <form class="data-filter surface" @submit.prevent="search"><div class="filter-keyword"><label for="data-search">关键词</label><el-input id="data-search" v-model="q" :placeholder="tab==='scenarios'?'场景名称 / 业务用途':'产品名称 / 企业 / 使用应用'" clearable/></div><div><label>分类</label><el-select v-model="theme" placeholder="全部分类" clearable aria-label="产品分类"><el-option v-for="v in tab==='scenarios'?['运输规划','运输执行','合作评估']:themes" :key="v" :label="v" :value="v"/></el-select></div><div v-if="!['catalog','scenarios'].includes(tab)"><label>状态</label><el-select v-model="state" placeholder="全部状态" clearable aria-label="服务状态"><el-option v-for="s in tab==='products'?['DRAFT','REVIEW','PUBLISHED','PAUSED','OFFLINE']:tab==='subscriptions'?['ACTIVE','EXPIRING','SCHEDULED','EXPIRED','PAUSED','REVOKED','UNAVAILABLE']:tab==='authorizations'&&recordTab==='grants'?['ACTIVE','SCHEDULED','EXPIRED','PAUSED','REVOKED']:['PENDING','APPROVED','REJECTED','WITHDRAWN']" :key="s" :label="label[s]" :value="s"/></el-select></div><div class="filter-actions"><el-button type="primary" native-type="submit">搜索</el-button><el-button @click="reset">重置</el-button></div></form>
   <header class="section-heading"><h2>{{({catalog:'业务数据产品',scenarios:'业务场景应用',authorizations:recordTab==='grants'?'授权台账':'授权申请',subscriptions:platform?'企业订阅':'我的订阅',operations:'企业授权审核',products:'产品登记与发布'} as any)[tab]}}<small>{{filtered.length}} {{tab==='catalog'?'项':'条'}}</small></h2><el-button v-if="tab==='products'&&platform" type="primary" @click="editProduct()"><Icon name="plus" :size="16"/>登记产品</el-button><span v-else-if="tab==='subscriptions'" class="muted">每日额度按 UTC 日期重置</span></header>
   <div v-if="tab==='catalog'" class="catalog-grid">
    <article v-for="p in shown" :key="p.id" class="data-card surface">
     <div class="card-content">
      <div class="card-heading">
       <button class="art-button" :aria-label="'查看'+p.name" @click="openProduct(p)"><Art :kind="p.dataset" compact/></button>
       <div class="card-heading-copy"><div class="card-eyebrow"><span>{{p.theme}}</span></div><button class="card-title" @click="openProduct(p)">{{p.profile.shortName}}</button><div class="card-publisher">平台运营 · 版本 {{p.version}}</div></div>
      </div>
      <p :title="p.description">{{p.description}}</p><div class="card-tags"><span>{{p.profile.scopeText}}</span><span>{{p.serviceMode==='BOTH'?'API · 文件':label[p.serviceMode]}}</span></div>
      <footer><span class="card-authorization" :class="{granted:applicant&&grantFor(p),pending:applicant&&pendingFor(p)&&!grantFor(p)}"><Icon :name="applicant&&grantFor(p)?'check':applicant&&pendingFor(p)?'clock':'shield'" :size="14"/>{{isPlatform?'平台统一授权':grantFor(p)?'已获授权':pendingFor(p)?'申请审核中':'按用途授权'}}</span><el-button link type="primary" @click="openProduct(p)">查看详情<Icon name="arrow" :size="16"/></el-button></footer>
     </div>
    </article>
    <a class="photo-credit" href="/assets/data-service/photo-credits.html" target="_blank" rel="noopener">图片来源</a>
   </div>
   <div v-else-if="tab==='scenarios'" class="scenario-grid"><article v-for="s in shown" :key="s.id" class="surface"><div class="scene-card-content"><div class="scene-card-heading"><Art :kind="s.datasets[0]"/><div><span class="eyebrow">{{s.category}}</span><h2>{{s.name}}</h2></div></div><p>{{s.description}}</p><div class="card-tags"><span v-for="p in s.products" :key="p.id">{{p.theme}}</span></div><footer><small>{{s.products.length}} 项关联数据产品</small><el-button link type="primary" @click="scenario=s">查看场景<Icon name="arrow" :size="16"/></el-button></footer></div></article></div>
   <div v-else-if="applicant&&tab==='subscriptions'" class="subscription-list"><article v-for="s in shown" :key="s.id" class="surface subscription-card"><Art :kind="s.authorization.product.dataset" compact/><div class="subscription-main"><div class="sub-title"><h3>{{s.authorization.product.profile?.shortName||s.authorization.product.name}}</h3><el-tag :type="type(statusOf(s))">{{label[statusOf(s)]}}</el-tag></div><p>{{s.name}}</p><div class="card-tags"><span>{{label[s.mode]}}</span><span>{{grantRange(s.authorization)}}</span><span>{{platform?s.entityName:''}}</span></div><div class="sub-period">{{date(s.authorization.startsAt)}} — {{date(s.authorization.expiresAt)}}<span>剩余 {{remain(s)}} 天</span></div></div><div class="quota-block"><small>今日调用 / 日额度</small><strong>{{s.usedToday}} <span>/ {{s.dailyLimit}}</span></strong><el-progress :percentage="Math.min(100,Math.round(s.usedToday/s.dailyLimit*100))" :show-text="false" :stroke-width="5"/><small>凭证 {{s.keyPrefix}}…</small></div><div class="sub-actions"><el-button type="primary" plain @click="manage(s)">管理订阅</el-button><el-button link @click="beginApply(s.authorization.product,s.authorization.constraints?.edition||'BASIC')">申请续期</el-button></div></article></div>
   <section v-else class="surface records-table"><el-table :data="shown">
    <template v-if="tab==='products'"><el-table-column label="产品" min-width="340"><template #default="{row}"><strong>{{row.name}}</strong><small class="block-muted">{{row.code}} · 版本 {{row.version}}</small></template></el-table-column><el-table-column prop="theme" label="分类" width="110"/><el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="type(row.status)">{{label[row.status]}}</el-tag></template></el-table-column><el-table-column label="登记时间" width="150"><template #default="{row}">{{date(row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="280"><template #default="{row}"><el-button link type="primary" @click="editProduct(row)">编辑新版本</el-button><el-button v-for="next in productNext[row.status]" :key="next" link type="primary" @click="change('products',row,next)">{{({REVIEW:'提交审核',PUBLISHED:row.status==='PAUSED'?'恢复':'发布',DRAFT:'转草稿',PAUSED:'暂停',OFFLINE:'下架'} as any)[next]}}</el-button></template></el-table-column></template>
    <template v-else><el-table-column label="数据产品" min-width="245"><template #default="{row}"><strong>{{row.product.profile?.shortName||row.product.name}}</strong><small class="block-muted">{{row.applicationName||row.purpose}}</small></template></el-table-column><el-table-column v-if="platform" prop="entityName" label="申请企业" min-width="210"/><el-table-column label="授权范围" min-width="150"><template #default="{row}">{{grantRange(row)}}</template></el-table-column><el-table-column label="期限" width="190"><template #default="{row}">{{date(row.startsAt)}}<small class="block-muted">至 {{date(row.expiresAt)}}</small></template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="type(row.effectiveStatus||row.status)">{{label[row.effectiveStatus||row.status]}}</el-tag></template></el-table-column><el-table-column label="操作" width="245"><template #default="{row}"><el-button link type="primary" @click="showRecord(row)">详情</el-button><template v-if="tab==='authorizations'&&recordTab==='grants'"><el-button v-if="applicant&&['ACTIVE','SCHEDULED'].includes(row.effectiveStatus)&&row.product.status==='PUBLISHED'&&row.productVersion===row.product.version" link type="primary" @click="beginSubscribe(row)">开通订阅</el-button><el-button v-if="platform&&row.status!=='REVOKED'" link @click="change('authorizations',row,row.status==='ACTIVE'?'PAUSED':'ACTIVE')">{{row.status==='ACTIVE'?'暂停':'恢复'}}</el-button><el-button v-if="platform&&row.status!=='REVOKED'" link @click="change('authorizations',row,'REVOKED')">撤销</el-button></template><template v-else><el-button v-if="platform&&row.status==='PENDING'" link type="primary" @click="beginReview(row)">审核</el-button><el-button v-if="applicant&&row.status==='PENDING'&&row.entityId===auth.user?.businessEntityId" link @click="withdraw(row)">撤回</el-button><el-button v-if="applicant&&['REJECTED','WITHDRAWN'].includes(row.status)&&row.entityId===auth.user?.businessEntityId" link @click="beginApply(row.product,row.edition)">重新申请</el-button></template></template></el-table-column></template>
   </el-table></section>
   <el-empty v-if="!shown.length&&!busy&&!error" :description="rows.length?'没有符合筛选条件的记录':isPlatform?'暂无数据服务记录': '尚无记录，可从数据产品申请所需服务'" :image-size="72"><el-button v-if="!rows.length&&tab!=='catalog'" @click="switchTab('catalog')">浏览数据产品</el-button><el-button v-else @click="reset">清空筛选</el-button></el-empty>
   <div v-if="filtered.length>12" class="data-pagination"><el-pagination v-model:current-page="page" :total="filtered.length" :page-size="12" layout="total, prev, pager, next"/></div>
  </template>

  <el-dialog v-if="applicant" class="data-service-dialog" v-model="applyOpen" title="申请数据授权" width="790px" :close-on-click-modal="false">
   <el-steps :active="applyStep" finish-status="success" simple><el-step title="填写申请"/><el-step title="确认提交"/><el-step title="申请结果"/></el-steps><div class="dialog-product"><Icon :name="applyProduct?.profile?.icon||'database'" :size="24"/><div><strong>{{applyProduct?.name}}</strong><small>{{applyProduct?.profile?.scopeText}}</small></div></div>
   <el-alert v-if="formError" :title="formError" type="error" :closable="false"/>
   <el-form v-if="applyStep===0" label-position="top" class="data-dialog-form"><div class="form-grid"><el-form-item label="申请企业"><el-input :model-value="auth.user?.businessEntity.name" disabled/><small>由当前登录企业提交 · <router-link to="/account" @click="applyOpen=false">查看账号</router-link></small></el-form-item><el-form-item label="申请部门" required><el-input v-model="application.department" placeholder="例如：物流业务部" maxlength="80"/></el-form-item><el-form-item label="使用应用 / 系统" required><el-input v-model="application.applicationName" maxlength="100"/></el-form-item><el-form-item label="申请版本" required><el-select v-model="application.edition"><el-option v-for="e in options.editions" :key="e.id" :value="e.id" :label="`${e.name} · 最多${e.dailyLimit}次/日`"/></el-select></el-form-item><el-form-item label="数据范围" required><el-select v-model="application.scope"><el-option v-for="s in applyProduct?.profile?.scopes" :key="s" :value="s" :label="label[s]"/></el-select></el-form-item><el-form-item label="授权期限" required><el-date-picker v-model="period" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" style="width:100%"/></el-form-item><template v-if="applyProduct?.dataset==='CAPACITY'"><el-form-item label="申请起运城市" required><el-input v-model="application.origin" placeholder="例如：营口市" maxlength="100"/></el-form-item><el-form-item label="申请目的城市" required><el-input v-model="application.destination" placeholder="例如：广州市" maxlength="100"/></el-form-item></template></div><el-form-item v-if="applyProduct?.dataset==='TRACE'" label="指定核验运单" required><el-select v-model="application.waybillIds" multiple filterable style="width:100%" :placeholder="options.waybills.length?'选择本企业获权运单':'本企业暂无可授权运单'"><el-option v-for="w in options.waybills" :key="w.id" :value="w.id" :label="w.waybillNo||w.businessNo"/></el-select><small>仅可申请本企业运单；核验时必须传入其中一个运单号。</small></el-form-item><el-form-item label="使用场景" required><el-checkbox-group v-model="application.scenarios"><el-checkbox v-for="s in ['运输规划','运输执行','合作评估','经营分析','其他']" :key="s" :value="s">{{s}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="数据使用用途" required><el-input v-model="application.purpose" type="textarea" :rows="3" minlength="10" maxlength="1000" show-word-limit placeholder="说明使用数据解决的业务问题，至少10字"/></el-form-item><div class="usage-agreement"><p>{{applyProduct?.conditions}}</p><el-checkbox v-model="application.accepted">按声明用途使用，不转授权，并接受范围与调用审计</el-checkbox></div></el-form>
   <div v-else-if="applyStep===1" class="apply-confirm"><el-descriptions :column="2" border><el-descriptions-item label="申请企业">{{auth.user?.businessEntity.name}}</el-descriptions-item><el-descriptions-item label="使用应用">{{application.applicationName}}</el-descriptions-item><el-descriptions-item label="申请版本">{{label[application.edition]}}</el-descriptions-item><el-descriptions-item label="数据范围">{{label[application.scope]}}</el-descriptions-item><el-descriptions-item label="期限" :span="2">{{period.join(' 至 ')}}</el-descriptions-item><el-descriptions-item v-if="application.origin" label="线路" :span="2">{{application.origin}} → {{application.destination}}</el-descriptions-item><el-descriptions-item v-if="application.waybillIds.length" label="运单" :span="2">{{application.waybillIds.map((id:string)=>options.waybills.find((w:any)=>w.id===id)?.waybillNo||options.waybills.find((w:any)=>w.id===id)?.businessNo).join('、')}}</el-descriptions-item><el-descriptions-item label="用途" :span="2">{{application.purpose}}</el-descriptions-item></el-descriptions><p>审核通过后，可在我的授权中开通所需订阅。</p></div>
   <el-result v-else icon="success" title="申请已提交" sub-title="平台运营方将审核使用用途、数据范围和期限。可在我的授权中查看进度与审核意见。"/>
   <template #footer><el-button v-if="applyStep<2" @click="applyOpen=false">取消</el-button><el-button v-if="applyStep===0" type="primary" @click="confirmApply">下一步</el-button><template v-else-if="applyStep===1"><el-button @click="applyStep=0">返回修改</el-button><el-button type="primary" :loading="saving" @click="submitApply">提交申请</el-button></template><el-button v-else type="primary" @click="applyOpen=false;switchTab('authorizations')">查看申请</el-button></template>
  </el-dialog>

  <el-dialog class="data-service-dialog" v-model="recordOpen" title="授权详情" width="720px"><template v-if="record"><h3>{{record.product.name}}</h3><el-descriptions :column="2" border><el-descriptions-item label="申请企业">{{record.entityName}}</el-descriptions-item><el-descriptions-item label="状态">{{label[record.effectiveStatus||record.status]}}</el-descriptions-item><el-descriptions-item label="数据范围" :span="2">{{grantRange(record)}}</el-descriptions-item><el-descriptions-item label="用途" :span="2">{{record.purpose}}</el-descriptions-item><el-descriptions-item label="期限" :span="2">{{date(record.startsAt)}} 至 {{date(record.expiresAt)}}</el-descriptions-item><el-descriptions-item v-if="record.reviewNote" label="审核意见" :span="2">{{record.reviewNote}}</el-descriptions-item><el-descriptions-item v-if="record.basis" label="授权依据" :span="2">{{record.basis}}</el-descriptions-item><el-descriptions-item v-if="record.dailyLimit" label="日额度">{{record.dailyLimit}}</el-descriptions-item><el-descriptions-item v-if="record.approver" label="审核人">{{record.approver}}</el-descriptions-item></el-descriptions><p>{{record.product.conditions}}</p></template><template #footer><el-button @click="recordOpen=false">关闭</el-button></template></el-dialog>
  <el-dialog class="data-service-dialog" v-model="reviewOpen" title="审核数据授权申请" width="750px"><template v-if="reviewRow"><h3>{{reviewRow.product.name}}</h3><el-descriptions :column="2" border><el-descriptions-item label="企业">{{reviewRow.entityName}}</el-descriptions-item><el-descriptions-item label="申请部门">{{reviewRow.department}}</el-descriptions-item><el-descriptions-item label="使用应用">{{reviewRow.applicationName}}</el-descriptions-item><el-descriptions-item label="版本">{{label[reviewRow.edition]}}</el-descriptions-item><el-descriptions-item label="范围" :span="2">{{grantRange(reviewRow)}}</el-descriptions-item><el-descriptions-item label="期限" :span="2">{{date(reviewRow.startsAt)}} 至 {{date(reviewRow.expiresAt)}}</el-descriptions-item><el-descriptions-item label="用途" :span="2">{{reviewRow.purpose}}</el-descriptions-item></el-descriptions><el-form label-position="top" class="data-dialog-form"><el-form-item label="审核结果"><el-radio-group v-model="review.status"><el-radio value="APPROVED">通过并授权</el-radio><el-radio value="REJECTED">退回</el-radio></el-radio-group></el-form-item><el-form-item v-if="review.status==='APPROVED'" label="授权日调用额度"><el-input-number v-model="review.dailyLimit" :min="1" :max="options.editions.find((e:any)=>e.id===reviewRow.edition)?.dailyLimit||100"/></el-form-item><el-form-item label="审核意见 / 授权依据" required><el-input v-model="review.note" type="textarea" :rows="3" maxlength="1000"/></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/></template><template #footer><el-button @click="reviewOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveReview">确认审核</el-button></template></el-dialog>
  <el-dialog v-if="applicant" class="data-service-dialog" v-model="subscribeOpen" title="开通数据订阅" width="560px"><template v-if="subscribeGrant"><h3>{{subscribeGrant.product.profile?.shortName||subscribeGrant.product.name}}</h3><p class="muted">{{grantRange(subscribeGrant)}} · 有效至 {{date(subscribeGrant.expiresAt)}}</p><el-form label-position="top"><el-form-item label="订阅名称" required><el-input v-model="subscribe.name" maxlength="100"/></el-form-item><el-form-item label="服务方式" required><el-radio-group v-model="subscribe.mode"><el-radio value="API" :disabled="subscribeGrant.product.serviceMode==='FILE'">API 服务</el-radio><el-radio value="FILE" :disabled="subscribeGrant.product.serviceMode==='API'">数据文件</el-radio></el-radio-group></el-form-item><el-form-item label="日调用额度" required><el-input-number v-model="subscribe.dailyLimit" :min="1" :max="subscribeGrant.dailyLimit"/><small>不超过授权额度 {{subscribeGrant.dailyLimit}} 次 / 日</small></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/></template><template #footer><el-button @click="subscribeOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveSubscribe">开通订阅</el-button></template></el-dialog>
  <el-dialog v-if="applicant" class="data-service-dialog" v-model="keyOpen" title="保存调用凭证" width="640px" :close-on-click-modal="false" @closed="issuedKey='' "><p>完整凭证仅在本次显示。请保存到业务应用中，列表仅保留前缀。</p><el-input :model-value="issuedKey" readonly type="textarea" :rows="3" aria-label="新调用凭证"/><template #footer><el-button @click="copyKey">复制凭证</el-button><el-button type="primary" @click="keyOpen=false">已保存</el-button></template></el-dialog>

  <el-drawer v-if="applicant" v-model="serviceOpen" title="订阅详情与调用" size="780px"><template v-if="activeSub"><h2>{{activeSub.authorization.product.profile?.shortName||activeSub.name}}</h2><div class="service-summary"><el-tag :type="type(statusOf(activeSub))">{{label[statusOf(activeSub)]}}</el-tag><span>{{activeSub.usedToday}} / {{activeSub.dailyLimit}} 次 · 今日</span><span>{{grantRange(activeSub.authorization)}}</span></div><el-tabs v-model="serviceTab"><el-tab-pane label="数据查询" name="query"><el-form label-position="top"><el-form-item v-if="activeSub.authorization.product.dataset==='TRACE'" label="获授权运单号" required><el-input v-model="query.waybillNo" placeholder="一次核验一个运单"/></el-form-item><div class="form-grid" v-if="activeSub.authorization.product.dataset==='CORRIDOR'"><el-form-item label="统计时段"><el-select v-model="query.period" placeholder="按周"><el-option value="DAY" label="按日"/><el-option value="WEEK" label="按周"/><el-option value="MONTH" label="按月"/></el-select></el-form-item><el-form-item label="起运地"><el-input v-model="query.origin"/></el-form-item><el-form-item label="目的地"><el-input v-model="query.destination"/></el-form-item><el-form-item label="开始日期"><el-date-picker v-model="query.from" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="query.to" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item></div><el-form-item v-if="activeSub.authorization.product.dataset==='CREDIT'" label="统计周期"><el-radio-group v-model="query.months"><el-radio value="3">近3个月</el-radio><el-radio value="12">近12个月</el-radio></el-radio-group></el-form-item><el-button type="primary" :loading="saving" @click="invoke">查询授权数据</el-button><el-button v-if="activeSub.mode==='FILE'" :loading="saving" @click="download()">下载数据文件</el-button><el-button :loading="saving" @click="download(true)">导出授权报告</el-button></el-form><el-alert v-if="queryError" :title="queryError" type="error" :closable="false"/><template v-if="result"><div class="result-heading"><strong>返回 {{result.data.length}} 条</strong><small>{{dateTime(result.asOf)}}</small></div><p class="muted">{{result.notes}}</p><el-empty v-if="!result.data.length" description="授权范围内暂无可提供的数据" :image-size="55"/><el-table v-else :data="result.data" max-height="460"><el-table-column v-for="f in Object.keys(result.data[0])" :key="f" :label="dataFieldLabels[f]||f" min-width="165"><template #default="{row}">{{valueText(row[f],f)}}</template></el-table-column></el-table></template></el-tab-pane><el-tab-pane label="调用记录" name="logs"><p class="muted">最近50次调用，包含成功与失败记录。</p><el-table :data="activeSub.calls"><el-table-column label="时间" width="175"><template #default="{row}">{{dateTime(row.createdAt)}}</template></el-table-column><el-table-column prop="channel" label="方式" width="105"/><el-table-column label="结果" width="85"><template #default="{row}"><el-tag :type="row.status==='SUCCESS'?'success':'danger'">{{row.status==='SUCCESS'?'成功':'失败'}}</el-tag></template></el-table-column><el-table-column prop="rows" label="条数" width="70"/><el-table-column prop="error" label="说明" min-width="200"/></el-table></el-tab-pane><el-tab-pane label="接口与管理" name="settings"><h3>调用接口</h3><pre class="code-block">GET /api/data-feed
X-Data-Key: {{activeSub.keyPrefix}}…
{{activeSub.authorization.product.dataset==='TRACE'?'查询参数：waybillNo=获授权运单号':''}}</pre><template v-if="activeSub.authorization.product.dataset==='RISK'"><h3>风险事件流</h3><pre class="code-block">GET /api/data-feed/events
X-Data-Key: 您的完整凭证</pre><p class="muted">通过 SSE 接收风险快照，每60秒检查一次，每次计入额度。暂停、撤销、到期或额度用尽时连接停止。</p></template><h3>订阅管理</h3><div class="subscription-controls"><el-button v-if="activeSub.status!=='REVOKED'" @click="rotate(activeSub)">轮换调用凭证</el-button><el-button v-if="activeSub.status!=='REVOKED'" @click="change('subscriptions',activeSub,activeSub.status==='ACTIVE'?'PAUSED':'ACTIVE')">{{activeSub.status==='ACTIVE'?'暂停订阅':'恢复订阅'}}</el-button><el-button v-if="activeSub.status!=='REVOKED'" type="danger" plain @click="change('subscriptions',activeSub,'REVOKED')">取消订阅</el-button></div><p>{{activeSub.authorization.product.conditions}}</p></el-tab-pane></el-tabs></template></el-drawer>
  <el-dialog class="data-service-dialog" v-model="productOpen" :title="editId?'编辑产品新版本':'登记数据产品'" width="820px"><el-form label-position="top"><div class="form-grid"><el-form-item label="产品编号" required><el-input v-model="productForm.code" :disabled="!!editId" maxlength="40"/></el-form-item><el-form-item label="产品名称" required><el-input v-model="productForm.name" maxlength="100"/></el-form-item><el-form-item label="分类" required><el-input v-model="productForm.theme" maxlength="100"/></el-form-item><el-form-item label="业务数据集" required><el-select v-model="productForm.dataset" @change="productForm.fields=[...options.datasets[productForm.dataset]]"><el-option v-for="(_,key) in options.datasets" :key="key" :value="key" :label="String(key)"/></el-select></el-form-item><el-form-item label="数据来源" required><el-input v-model="productForm.source" maxlength="500"/></el-form-item><el-form-item label="覆盖范围" required><el-input v-model="productForm.coverage" maxlength="500"/></el-form-item><el-form-item label="服务方式"><el-select v-model="productForm.serviceMode"><el-option value="API" label="API"/><el-option value="FILE" label="文件"/><el-option value="BOTH" label="API与文件"/></el-select></el-form-item><el-form-item label="更新频率"><el-select v-model="productForm.frequency"><el-option v-for="f in ['实时','每小时','每日','按需']" :key="f" :value="f"/></el-select></el-form-item><el-form-item label="输出格式"><el-select v-model="productForm.format"><el-option value="JSON"/><el-option value="CSV"/></el-select></el-form-item><el-form-item label="运营方"><el-input v-model="productForm.owner" maxlength="100"/></el-form-item></div><el-form-item label="产品介绍" required><el-input v-model="productForm.description" type="textarea" :rows="3" maxlength="2000"/></el-form-item><el-form-item label="数据字段白名单" required><el-checkbox-group v-model="productForm.fields"><el-checkbox v-for="f in options.datasets[productForm.dataset]" :key="f" :value="f">{{dataFieldLabels[f]||f}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="数据使用约定" required><el-input v-model="productForm.conditions" type="textarea" :rows="3" maxlength="2000"/></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button @click="productOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveProduct">保存草稿</el-button></template></el-dialog>
 </div>
</template>
<style scoped src="./data-service.css"></style>
